package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * A new DRAFT claim, dated (when left undated) the sheet's entry date while it is set, else its today, its due-by fixed now: its date plus its person's own terms, else the terms of their grade on that date, else the sheet's.
 * Dated inside a soft-closed period, it is a late entry.
 */
public class BuildClaim {
    public void build(@Val ClaimInput input, @Val Sheet sheet, @Val Person person, SettingsRepository settings,
            PeriodRepository periods,
            Out<Claim> claimOut) {
        Settings terms = settings.find(sheet.id());
        LocalDate date = input.date() == null ? terms.entryDay(sheet.today()) : input.date();
        Claim claim = new Claim(null, sheet.id(), person.getId(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null);
        claim.setCorrects(input.corrects());
        claim.setDueBy(date.plusDays(terms.termsFor(person, date)));
        claim.setLateEntry(periods.softClosedOn(sheet.id(), date) != null);
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim)
            throws InvalidClaimStatusException {
        claim.checkEditable();
        claim.setAmount(input.amount());
        claim.setDate(input.date() == null ? sheet.today() : input.date());
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The number a claim being opened takes: the sheet's next (1, 2, ...), or, while the sheet's period
 * numbering from is set and its today is on or after it, the next within the claim's period
 * (<period name>-<n>), or X-<n> when the claim is in no period.
 */
final class ClaimNumbers {
    private ClaimNumbers() {}

    static String next(Sheet sheet, Claim claim, Settings settings, PeriodRepository periods, ClaimRepository claims) {
        if (!settings.numbersByPeriod(sheet.today())) return String.valueOf(claims.nextNumber(sheet.id()));
        Period period = periods.findAll(sheet.id()).stream()
                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
        if (period == null) return "X-" + claims.nextNumberIn(sheet.id(), "");
        return period.name() + "-" + claims.nextNumberIn(sheet.id(), period.name());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Gives a claim being opened its number (the sheet's next, or the next within its period); refused
 * when another request opened it first.
 */
public class NumberClaim {
    public void number(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository, SettingsRepository settings,
            PeriodRepository periods) throws InvalidClaimStatusException {
        if (!repository.markOpened(claim)) throw new InvalidClaimStatusException(ClaimStatus.DRAFT, ClaimStatus.OPEN);
        claim.setNumber(ClaimNumbers.next(sheet, claim, settings.find(sheet.id()), periods, repository));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.Objects;
import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-dates an OPEN or PENDING claim (a steward). Its new date may not be after its person's
 * retirement nor inside a closed period. Its due-by and any figure a statement bound it to are kept;
 * its period follows the new date, and while numbering by period, a claim whose period changes takes
 * the next number of its new period's sequence (its old number is never used again).
 */
public class RedateClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, @Val Redate redate, PersonRepository people,
            RoleRepository roles, SettingsRepository settings, PeriodRepository periods, ClaimRepository claims,
            HttpServletRequest request, Out<Redating> redatingOut)
            throws StewardOnlyException, InvalidClaimStatusException, RetiredPersonException, ClosedPeriodException {
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), Audit.user(request)))) {
            throw new StewardOnlyException("Only a steward may re-date a claim");
        }
        if (!claim.isOpen()) {
            throw new InvalidClaimStatusException("A " + claim.getStatus() + " claim cannot be re-dated");
        }
        LocalDate to = redate.date();
        Person person = people.find(sheet.id(), claim.getPersonId());
        if (person != null && person.retiredBefore(to)) throw new RetiredPersonException(person.getName());
        Period closed = periods.closedOn(sheet.id(), to);
        if (closed != null) throw new ClosedPeriodException(closed.name());

        LocalDate from = claim.getDate();
        String periodBefore = periodOf(periods, sheet, from);
        claim.setDate(to);
        Settings sheetSettings = settings.find(sheet.id());
        if (sheetSettings.numbersByPeriod(sheet.today()) && !Objects.equals(periodBefore, periodOf(periods, sheet, to))) {
            claim.setNumber(ClaimNumbers.next(sheet, claim, sheetSettings, periods, claims));
        }
        redatingOut.set(new Redating(from, to));
    }

    private static String periodOf(PeriodRepository periods, Sheet sheet, LocalDate date) {
        return periods.findAll(sheet.id()).stream().filter((p) -> p.contains(date))
                .map(Period::name).findFirst().orElse(null);
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Splits an amount off an OPEN claim: the claim keeps the rest, unbound from any statement, and a new
 * OPEN claim with the amount split off, its date and note, opened by the signed-in user and its
 * due-by fixed now from the terms in force on its date, is made. Only a role the permission matrix
 * allows to open a claim may split one (the new claim is theirs to open).
 */
public class SplitClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, @Val SplitAmount split, RoleRepository roles,
            SettingsRepository settingsRepository, PersonRepository people, HttpServletRequest request,
            Out<Split> splitOut) throws InvalidClaimStatusException, InvalidClaimException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        Settings settings = settingsRepository.find(sheet.id());
        if (!settings.allows("open", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not split a claim");
        }
        claim.split(split.amount(), sheet.today());
        Person person = people.find(sheet.id(), claim.getPersonId());
        Claim made = new Claim(null, sheet.id(), claim.getPersonId(), split.amount(), claim.getDate(),
                claim.getNote(), ClaimStatus.OPEN, null, null, user);
        made.setSplitFrom(claim.getNumber());
        made.setDueBy(claim.getDate().plusDays(settings.termsFor(person, claim.getDate())));
        splitOut.set(new Split(made));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.CheckClaimPeriod;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.PeriodRepository;
